-- Bloco 10/10: 10 perguntas de O Que é o Espiritismo.
-- Seguro para executar individualmente; não altera perguntas existentes.
INSERT INTO public.questions
  (book, statement, option_a, option_b, option_c, option_d, option_e,
   correct_option, explanation, reference, difficulty, active)
VALUES
  ('o_que_e_espiritismo', 'No Segundo Diálogo (''O Cético''), como Allan Kardec explica o fenômeno das aparições visíveis e até tangíveis (agêneres) de Espíritos?', 'Pela condensação momentânea do fluido perispiritual combinada ao fluido emitido por um médium de efeitos físicos, tornando o perispírito visível e por vezes palpável.', 'Pela ressurreição definitiva da carne e dos ossos que estavam no cemitério.', 'Por simples ilusão de óptica causada por espelhos côncavos nas salas.', 'Pela transformação química do oxigênio do ar em tecido muscular permanente.', 'Pelo desdobramento exclusivo dos animais domésticos presentes na casa.', 'A', 'Em estado normal o perispírito é invisível para os nossos olhos materiais, mas por uma modificação molecular e combinação com o fluido de certos médiuns pode condensar-se até tornar-se visível e momentaneamente tangível.', 'O Que é o Espiritismo - Cap. I, Segundo Diálogo: O Cético', 'dificil', true),
  ('o_que_e_espiritismo', 'No Segundo Diálogo, por que Allan Kardec afirma que no Espiritismo não há nada de sobrenatural nem de maravilhoso?', 'Porque o Espiritismo nega a existência de Deus e da alma imortal.', 'Porque todos os fenômenos espíritas repousam sobre leis da Natureza até então desconhecidas; uma vez conhecida a lei que os rege, o maravilhoso desaparece.', 'Porque todas as manifestações mediúnicas são meros truques de prestidigitação.', 'Porque os Espíritos são feitos de matéria sólida idêntica ao ferro.', 'Porque a Ciência já conhecia o perispírito desde a antiguidade clássica.', 'B', 'Deus não derroga as próprias leis que estabeleceu; o que parecia sobrenatural ou miraculoso na ignorância das leis fluídicas e espirituais entra na ordem dos fenômenos naturais explicados pelo Espiritismo.', 'O Que é o Espiritismo - Cap. I, Segundo Diálogo: O Cético', 'facil', true),
  ('o_que_e_espiritismo', 'No Terceiro Diálogo (''O Padre''), como o espírita responde à pergunta sobre se o Espiritismo é uma nova religião?', 'Afirmando que o Espiritismo tem bispos, dogmas fechados e sacramentos próprios.', 'Dizendo que o Espiritismo proíbe seus adeptos de entrarem em qualquer igreja.', 'Explicando que o Espiritismo é uma ciência de observação e uma doutrina filosófica de consequências morais que não possui culto material, sacerdócio nem templos, proclamando a liberdade de consciência.', 'Declarando que o Espiritismo exige o batismo obrigatório nas águas do rio Sena.', 'Sustentando que a moral espírita é oposta ao ensino de Jesus Cristo.', 'C', 'Em O Que é o Espiritismo, Kardec esclarece ao Padre que o Espiritismo não se constitui como igreja com sacerdócio ou rituais exteriores, mas acolhe homens de todas as crenças na vivência da caridade cristã.', 'O Que é o Espiritismo - Cap. I, Terceiro Diálogo: O Padre', 'dificil', true),
  ('o_que_e_espiritismo', 'Segundo o Capítulo II (itens 31 a 34), todos os Espíritos que são evocados podem atender imediatamente ao chamado?', 'Sim, qualquer Espírito é obrigado a comparecer no instante em que seu nome é pronunciado.', 'Não, porque nenhum Espírito pode jamais ouvir o pensamento dos encarnados.', 'Sim, desde que o evocador pronuncie o nome do Espírito três vezes em voz alta.', 'Não; o Espírito pode estar reencarnado ou ocupado em missão distante, ou a permissão pode ser-lhe negada; nesse caso, ou avisa que não pode vir, ou um Espírito amigo responde por ele.', 'Apenas os Espíritos sofredores têm permissão de atender às evocações.', 'D', 'Kardec explica nos itens 32 a 34 que diversas causas podem impedir a comunicação imediata de um Espírito evocado, inclusive o fato de achar-se reencarnado na Terra ou em outro mundo.', 'O Que é o Espiritismo - Cap. II, itens 31 a 34', 'expert', true),
  ('o_que_e_espiritismo', 'No Capítulo II (itens 50 a 54), o que recomenda Allan Kardec àquele que deseja verificar experimentalmente se possui a faculdade de médium escrevente (psicógrafo)?', 'Submeter-se antes a um jejum rigoroso de sete dias no escuro.', 'Comprar aparelhos magnéticos de cobre e cristal.', 'Ingerir substâncias narcóticas para provocar o transe.', 'Exigir que os Espíritos movam os móveis da sala como sinal prévio.', 'Recolher-se em silêncio com fé, elevar o pensamento em prece ao seu Espírito protetor e aguardar com paciência e perseverança, renovando a tentativa por vários dias sem desanimar.', 'E', 'Nos itens 50 a 54, Kardec ensina que o meio de tentar é simples: recolhimento, prece sincera ao anjo guardião e aos bons Espíritos, evitando perguntas frívolas ou interesseiras e perseverando com calma.', 'O Que é o Espiritismo - Cap. II, itens 50 a 54', 'medio', true),
  ('o_que_e_espiritismo', 'Segundo o Capítulo II (itens 57 a 62), quais são os sinais característicos pelos quais se reconhece a obsessão e a fascinação mediúnica?', 'A exigência do Espírito de que o médium se isole, rejeite todo exame crítico alheio, escreva incessantemente coisas pueris ou absurdas e acredite cegamente em sua própria infalibilidade.', 'O conselho constante para estudar, praticar a caridade e submeter os escritos ao crivo da razão.', 'A raridade das comunicações e a brevidade das respostas morais.', 'A recomendação de respeitar os deveres familiares e profissionais.', 'O estímulo à humildade, à paciência e ao perdão das ofensas.', 'A', 'Todo Espírito que receia o exame e a discussão, que isola o médium dos conselhos prudentes, que impõe ordens ridículas ou lisonjeia o orgulho é infalivelmente um Espírito mistificador e obsessor.', 'O Que é o Espiritismo - Cap. II, itens 57 a 62', 'dificil', true),
  ('o_que_e_espiritismo', 'De acordo com o Capítulo III (itens 108 e 109), a alma existe antes da formação do corpo físico que vai animar?', 'Não; a alma é criada no exato instante em que o recém-nascido respira.', 'Sim; a alma preexiste à união com o corpo, pois é um Espírito que já viveu na erraticidade e em existências anteriores.', 'Apenas as almas dos profetas preexistiam ao nascimento.', 'Não, porque a alma é uma secreção produzida pelo cérebro infantil.', 'Somente nos planetas superiores a alma existe antes do corpo.', 'B', 'No item 109, Kardec afirma categoricamente a preexistência da alma: antes de unir-se ao corpo, ela é um dos Espíritos que povoam o mundo invisível e que se encarna para progredir.', 'O Que é o Espiritismo - Cap. III, itens 108 e 109', 'medio', true),
  ('o_que_e_espiritismo', 'Segundo o Capítulo III (itens 122 e 125), como se dá a separação entre a alma e o corpo no momento da morte?', 'De forma sempre instantânea e acompanhada de dores físicas lancinantes para todos os homens.', 'Somente após a decomposição total dos ossos no sepulcro.', 'Gradualmente, desatando-se os laços fluídicos do perispírito sem dor maior do que na vida; para o justo, a separação é pronta e suave como o despertar de um sono.', 'Mediante o rompimento mecânico da coluna vertebral.', 'Apenas quando o sol se põe no horizonte local.', 'C', 'No item 122, Kardec explica que a separação não é brusca nem dolorosa em si mesma: o corpo frequentemente sofre mais durante a vida e a moléstia do que no momento do desprendimento final.', 'O Que é o Espiritismo - Cap. III, itens 122 e 125', 'expert', true),
  ('o_que_e_espiritismo', 'Conforme o Capítulo III (itens 131 e 132), o que fazem os Espíritos durante o estado de erraticidade?', 'Dormem em letargia profunda até o momento de reencarnar.', 'Ficam presos imóvelmente ao redor do próprio túmulo.', 'Perdem o livre-arbítrio e tornam-se autômatos inconscientes.', 'Refletem sobre a existência passada, instruem-se, procuram meios de se adiantar e escolhem novas provas para as futuras encarnações.', 'Dedicam-se exclusivamente a produzir ruídos materiais nas casas.', 'D', 'Na erraticidade, o Espírito esclarecido estuda o seu passado, reconhece seus erros, frequenta centros de instrução espiritual e prepara as provas que lhe permitirão avançar em nova existência.', 'O Que é o Espiritismo - Cap. III, itens 131 e 132', 'facil', true),
  ('o_que_e_espiritismo', 'Na conclusão de ''O Que é o Espiritismo'', qual é a síntese prática de toda a moral ensinada pelos Espíritos Superiores?', 'O isolamento absoluto do mundo social e a renúncia ao trabalho.', 'A busca do poder terreno e da supremacia intelectual sobre os semelhantes.', 'A observância exclusiva de cerimônias exteriores sem reforma íntima.', 'O fatalismo resignado que dispensa o esforço de aperfeiçoamento.', 'O amor a Deus acima de tudo e a caridade para com o próximo — benevolência para com todos, indulgência para as imperfeições alheias e perdão das ofensas.', 'E', 'Toda a filosofia moral de O Que é o Espiritismo converge para a máxima evangélica da caridade ativa, da fraternidade e da reforma íntima como condição indispensável da felicidade futura.', 'O Que é o Espiritismo - Cap. II, itens 98 a 104 / Cap. III', 'facil', true);

SELECT COUNT(*) AS perguntas_do_livro
FROM public.questions
WHERE book = 'o_que_e_espiritismo';